import{_ as t,o as d,c as r,Q as a}from"./chunks/framework.b2e9bf53.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"专题/待收录整理专题.md","filePath":"专题/待收录整理专题.md","lastUpdated":null}'),e={name:"专题/待收录整理专题.md"},o=a('<h2 id="性能优化" tabindex="-1">性能优化 <a class="header-anchor" href="#性能优化" aria-label="Permalink to &quot;性能优化&quot;">​</a></h2><blockquote><p>平时都用了哪些方法进行性能优化？</p></blockquote><p>减少http请求次数、打包压缩上线代码、使用懒加载、使用雪碧图、动态渲染组件、CDN加载包。</p><blockquote><p>图片懒加载是怎么实现的？</p></blockquote><blockquote><p>其他优化</p></blockquote><ol><li>首屏优化</li><li>webpack</li><li>打包优化</li><li>网络</li><li>dom操作</li><li>合成层</li><li>Seo引擎优化</li><li>JS优化 隐藏类Hidden Class</li></ol><blockquote><p>优化入手方向</p></blockquote><ul><li>减少前端资源数量，减小前端资源大小，减少dom操作</li><li>代码层面：注意事件的销毁、路由懒加载、提取公共代码、css放前面、组件懒加载、减少代码体积大小、字体图标代替图片、使用事件委托、使用查找表、不覆盖原生方法、减低css选择器复杂度、使用flex、使用 transform 和 opacity实现动画</li><li>交互优化：减少请求数量、使用 HTTP2（头部压缩、链路复用、解析快、可设置优先级、流量控制、服务器推送）、减少重绘重排（innerHTML代替DOM操作、避免使用动态属性、脱离文档流操作再合并）</li><li>加载优化：按需引入、使用CDN、使用服务端渲染、善用缓存、避免卡顿</li><li>打包优化：使用gzip、Webpack 对图片进行压缩、webpack 按需加载代码、提取第三库代码、webpack物理打包以及配置项打包优化</li><li>其他优化：图片优化（压缩、懒加载、用webp格式，延迟加载、响应式图片）、使用工作线程Web Workers、少用全局变量</li></ul><h2 id="低代码" tabindex="-1">低代码 <a class="header-anchor" href="#低代码" aria-label="Permalink to &quot;低代码&quot;">​</a></h2><h2 id="服务端渲染ssr" tabindex="-1">服务端渲染SSR <a class="header-anchor" href="#服务端渲染ssr" aria-label="Permalink to &quot;服务端渲染SSR&quot;">​</a></h2><p>服务端渲染 SSR与客户端渲染CSR(同构渲染)</p><p>SSR：在服务器端渲染 HTML 给客户端，提升首屏性能 + SEO；</p><p>CSR：客户端渲染，交互丰富。同构渲染指服务端和客户端共享代码、渲染逻辑。在使用 Next.js／Nuxt.js 时会经常接触这个概念。</p><h2 id="国际化" tabindex="-1">国际化 <a class="header-anchor" href="#国际化" aria-label="Permalink to &quot;国际化&quot;">​</a></h2><h2 id="跨端开发" tabindex="-1">跨端开发 <a class="header-anchor" href="#跨端开发" aria-label="Permalink to &quot;跨端开发&quot;">​</a></h2><h2 id="小程序开发" tabindex="-1">小程序开发 <a class="header-anchor" href="#小程序开发" aria-label="Permalink to &quot;小程序开发&quot;">​</a></h2><p>微信登录接口</p><h2 id="移动端开发" tabindex="-1">移动端开发 <a class="header-anchor" href="#移动端开发" aria-label="Permalink to &quot;移动端开发&quot;">​</a></h2><h2 id="前端安全" tabindex="-1">前端安全 <a class="header-anchor" href="#前端安全" aria-label="Permalink to &quot;前端安全&quot;">​</a></h2><h2 id="前端微服务" tabindex="-1">前端微服务 <a class="header-anchor" href="#前端微服务" aria-label="Permalink to &quot;前端微服务&quot;">​</a></h2><p>qiankun:一个用于构建 微前端（Micro-Frontends）系统的解决方案，支持隔离样式、JS 沙箱、子应用预加载等。</p><h2 id="设计模式" tabindex="-1">设计模式 <a class="header-anchor" href="#设计模式" aria-label="Permalink to &quot;设计模式&quot;">​</a></h2><p>在前端工程化中常提及（如模块化、组件化、依赖注入、观察者模式、策略模式等）。</p><h2 id="微前端" tabindex="-1">微前端 <a class="header-anchor" href="#微前端" aria-label="Permalink to &quot;微前端&quot;">​</a></h2><p>架构思想：将前端大应用拆分为多个可独立部署／独立团队维护的子应用。与微服务理念类似，在前端层面应用。</p><h2 id="gis开发" tabindex="-1">GIS开发 <a class="header-anchor" href="#gis开发" aria-label="Permalink to &quot;GIS开发&quot;">​</a></h2><p>大数据GIS</p><p>服务端GIS</p><p>桌面GIS</p><p>ArcGIS</p><p>GeoServer</p><p>SuperMap</p><h2 id="quasar" tabindex="-1">Quasar <a class="header-anchor" href="#quasar" aria-label="Permalink to &quot;Quasar&quot;">​</a></h2><h2 id="seo优化" tabindex="-1">SEO优化 <a class="header-anchor" href="#seo优化" aria-label="Permalink to &quot;SEO优化&quot;">​</a></h2><p>在 Web 应用中优化搜索引擎可见性（如首屏渲染、语义化标签、性能优化、结构化数据等）。对于 SSR／静态生成的框架尤为重要。</p><h2 id="web服务器" tabindex="-1">Web服务器 <a class="header-anchor" href="#web服务器" aria-label="Permalink to &quot;Web服务器&quot;">​</a></h2><h2 id="webgl" tabindex="-1">WebGL <a class="header-anchor" href="#webgl" aria-label="Permalink to &quot;WebGL&quot;">​</a></h2><p>数字孪生低代码3D框架-UINO优诺ThingJS</p><p>three.js</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><table><thead><tr><th>名称</th><th>性质</th><th>简要介绍</th><th>主要作用</th></tr></thead><tbody><tr><td><strong>dhtmlx-Gantt（甘特图）</strong></td><td>技术（库）</td><td>JavaScript 甘特图组件，用于任务进度和依赖可视化</td><td>实现项目进度管理、任务排期展示</td></tr><tr><td><strong>Hooks</strong></td><td>概念/技术</td><td>React 中的函数式状态逻辑机制（如 useState、useEffect）</td><td>在函数组件中使用状态与生命周期</td></tr><tr><td><strong>session</strong></td><td>概念</td><td>服务端存储用户会话信息的机制</td><td>维持用户登录状态、跨请求身份识别</td></tr><tr><td><strong>Socket 通信</strong></td><td>技术</td><td>服务器与客户端间的双向实时通信机制</td><td>实现消息推送、聊天室、协作等实时功能</td></tr><tr><td><strong>Store</strong></td><td>概念</td><td>前端应用中的全局状态仓库（如 Vuex、Redux）</td><td>统一管理和共享组件间的状态数据</td></tr><tr><td><strong>Mongoose</strong></td><td>技术（库）</td><td>Node.js 的 MongoDB 对象建模工具（ODM）</td><td>方便定义数据模型、验证与数据库交互</td></tr><tr><td><strong>WebSocket</strong></td><td>技术（协议）</td><td>浏览器与服务器之间的全双工通信协议</td><td>实现实时更新、推送通知等功能</td></tr><tr><td><strong>XSS / CSRF</strong></td><td>概念</td><td>常见前端安全漏洞：跨站脚本攻击 / 请求伪造</td><td>防止代码注入与恶意请求</td></tr><tr><td><strong>持久化存储</strong></td><td>概念</td><td>数据长期保存在本地，如 localStorage、IndexedDB</td><td>保持用户数据、实现离线应用</td></tr><tr><td><strong>TypeORM</strong></td><td>技术（框架）</td><td>基于 TypeScript 的 ORM 框架，支持多种数据库</td><td>对象化数据库操作，提高开发效率</td></tr><tr><td><strong>同构渲染</strong></td><td>概念</td><td>前后端共用同一份渲染逻辑（SSR+CSR）</td><td>提升首屏加载速度与 SEO 效果</td></tr><tr><td><strong>CI/CD + Docker 自动化部署</strong></td><td>技术（工程实践）</td><td>结合 CI/CD 管线与 Docker 容器实现持续集成与部署</td><td>自动构建、测试、部署项目</td></tr><tr><td><strong>Cache-Control</strong></td><td>技术（HTTP 头）</td><td>HTTP 缓存控制字段（如 max-age、no-cache）</td><td>控制浏览器和中间代理缓存策略</td></tr><tr><td><strong>强缓存</strong></td><td>概念</td><td>浏览器在缓存未过期前直接使用本地资源</td><td>加快资源加载，减少请求数</td></tr><tr><td><strong>中间服务</strong></td><td>概念/架构</td><td>位于前后端之间的代理或聚合层</td><td>做鉴权、缓存、限流、数据聚合等</td></tr><tr><td><strong>Expires</strong></td><td>技术（HTTP 头）</td><td>指定资源缓存的绝对过期时间</td><td>早期缓存控制机制（已被 Cache-Control 替代）</td></tr><tr><td><strong>Cache API</strong></td><td>技术（Web API）</td><td>Service Worker 中的缓存接口</td><td>实现离线缓存、自定义资源更新策略</td></tr><tr><td><strong>Service Worker</strong></td><td>技术（浏览器机制）</td><td>浏览器后台脚本，可拦截请求、缓存内容</td><td>支持离线访问、PWA、消息推送</td></tr><tr><td><strong>静态资源</strong></td><td>概念</td><td>网站中不会频繁变动的文件（JS、CSS、图片）</td><td>提高加载性能、配合 CDN 加速</td></tr><tr><td><strong>CDN 边缘节点</strong></td><td>技术</td><td>CDN 网络中的就近缓存服务器</td><td>提供资源的本地加速访问</td></tr><tr><td><strong>CDN 网络</strong></td><td>技术/架构</td><td>内容分发网络，通过节点分发资源</td><td>减少延迟，提高全球访问速度</td></tr><tr><td><strong>分层缓存</strong></td><td>概念</td><td>浏览器、CDN、代理、服务端多级缓存策略</td><td>提升整体系统性能与响应速度</td></tr><tr><td><strong>hash</strong></td><td>技术（构建机制）</td><td>根据文件内容或时间生成的指纹值</td><td>控制版本与缓存失效</td></tr><tr><td><strong>contenthash</strong></td><td>技术（构建机制）</td><td>根据文件内容生成稳定哈希</td><td>仅内容变更时更新哈希，避免缓存浪费</td></tr><tr><td><strong>协商缓存</strong></td><td>概念</td><td>资源变更由服务器校验（ETag/Last-Modified）</td><td>节省带宽，保持最新资源</td></tr><tr><td><strong>CI/CD 集成</strong></td><td>技术/概念</td><td>持续集成与持续交付自动化流程</td><td>自动化构建、测试、部署，提高效率</td></tr><tr><td><strong>oops joe</strong></td><td>概念（假设为 OOPs，面向对象编程）</td><td>OOPs 为面向对象设计理念（封装、继承、多态）</td><td>提高代码复用与可维护性</td></tr><tr><td><strong>Adobe Illustrator</strong></td><td>工具</td><td>专业矢量图形设计软件</td><td>绘制 UI、图标、矢量插画</td></tr><tr><td><strong>Tailwind CSS</strong></td><td>技术（框架）</td><td>原子化 CSS 框架，使用类名快速构建样式</td><td>高效开发、统一设计系统</td></tr><tr><td><strong>Redux</strong></td><td>技术（库）</td><td>JavaScript 状态管理工具，基于单向数据流</td><td>管理复杂应用的全局状态</td></tr></tbody></table><p>前端自动化性能测试 网站部署方案 CSS BEM命名法 模块化分离组件代码 watchEffect中的异步问题 封装resize指令 Intersection Ovserver 浏览器指纹 静态资源的静态访问 拖拽API PostCSS</p>',42),s=[o];function n(l,i,h,c,p,g){return d(),r("div",null,s)}const S=t(e,[["render",n]]);export{u as __pageData,S as default};
